INSERT INTO custom_events (id, name, event_date, content, location) VALUES ('22222222-2222-2222-2222-000000000001', 'Giỗ Thủy Tổ Nguyễn Mậu Thái (Phúc Hội)', '2026-07-18', 'Ngày kỵ nhật Thủy Tổ Họ Nguyễn Mậu tại Cổ Lễ (Mồng 5 tháng 6 Âm lịch). Con cháu toàn họ tề tựu tế lễ tại Từ đường Thượng Đền.', 'Từ đường Họ Nguyễn Mậu, Thôn Thượng Đền, Cổ Lễ');
INSERT INTO custom_events (id, name, event_date, content, location) VALUES ('22222222-2222-2222-2222-000000000002', 'Giỗ Tổ Tướng Công Nguyễn Mậu Hoàn (Ngành 4)', '2026-02-28', 'Ngày kỵ nhật Tướng Công Nguyễn Mậu Hoàn (Tự Tuấn Thông / Viết Nghĩa, 12 tháng Giêng Âm lịch). Triều đình cấp 100 mẫu ruộng và dân làng tế tự.', 'Từ đường Ngành 4, Thôn Thượng Đền, Cổ Lễ');
INSERT INTO custom_events (id, name, event_date, content, location) VALUES ('22222222-2222-2222-2222-000000000003', 'Giỗ Tổ Ngành Nhất Nguyễn Mậu Trường (Phúc Tiên)', '2026-11-09', 'Ngày kỵ nhật Tổ Ngành Nhất (Mồng 1 tháng 10 Âm lịch). Tế lễ tại Từ đường Ngành Nhất.', 'Từ đường Ngành Nhất, Thôn Thượng Đền');
INSERT INTO custom_events (id, name, event_date, content, location) VALUES ('22222222-2222-2222-2222-000000000004', 'Lễ Hội Chùa Cổ Lễ & Đền Thượng Lãng', '2026-10-24', 'Lễ hội truyền thống Chùa Cổ Lễ và Đền Thượng tưởng nhớ Đức Thánh Nguyễn Minh Không (13-16 tháng 9 Âm lịch).', 'Chùa Cổ Lễ & Đền Thượng Lãng');
